package localchat;
import java.awt.*;import java.awt.event.*;import java.nio.file.*;import java.util.*;import java.util.List;import java.util.concurrent.atomic.AtomicInteger;import javax.swing.*;
public final class SidebarNavigationTest {
 static int checks;static void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
 public static void main(String[] args)throws Exception{
  Path root=Files.createTempDirectory(Files.createDirectories(Path.of(System.getProperty("localchat.home"))),"run-");Conversations.State state=new Conversations.State();Path file=Conversations.newFile(root);state.title="Saved chat";Conversations.save(file,root.toString(),List.of(ChatClient.Message.user("Saved prompt")),state);var saved=Conversations.load(file);AtomicInteger opens=new AtomicInteger();WorkspacePanel[] panel={null};JFrame[] frame={null};
  FeatureTest.edt(()->{panel[0]=new WorkspacePanel(()->{},s->opens.incrementAndGet(),()->{},()->{});panel[0].refresh(List.of(saved));frame[0]=new JFrame();frame[0].add(panel[0]);frame[0].setSize(300,750);frame[0].addNotify();frame[0].validate();panel[0].archived.doClick();check(panel[0].sessions.isEmpty()&&panel[0].resetFilters.isVisible(),"archive-only empty list explains active filter");panel[0].resetFilters.doClick();check(panel[0].sessions.size()==1&&!panel[0].archived.isSelected(),"reset restores active chats without changing archive");check(!Conversations.load(file).state().archived,"filter never archives or deletes chat");panel[0].list.clearSelection();});
  JList<?> list=panel[0].list;Point point=new Point(20,10);
  // Posted AWT events reproduce pointer navigation without native input or an external desktop.
  long now=System.currentTimeMillis();for(MouseEvent e:List.of(new MouseEvent(list,MouseEvent.MOUSE_PRESSED,now,InputEvent.BUTTON1_DOWN_MASK,point.x,point.y,1,false,MouseEvent.BUTTON1),new MouseEvent(list,MouseEvent.MOUSE_RELEASED,now+10,0,point.x,point.y,1,false,MouseEvent.BUTTON1),new MouseEvent(list,MouseEvent.MOUSE_CLICKED,now+10,0,point.x,point.y,1,false,MouseEvent.BUTTON1),new MouseEvent(list,MouseEvent.MOUSE_PRESSED,now+70,InputEvent.BUTTON1_DOWN_MASK,point.x,point.y,2,false,MouseEvent.BUTTON1),new MouseEvent(list,MouseEvent.MOUSE_RELEASED,now+80,0,point.x,point.y,2,false,MouseEvent.BUTTON1),new MouseEvent(list,MouseEvent.MOUSE_CLICKED,now+80,0,point.x,point.y,2,false,MouseEvent.BUTTON1)))Toolkit.getDefaultToolkit().getSystemEventQueue().postEvent(e);
  FeatureTest.edt(()->check(opens.get()==0,"mouse navigation waits until click sequence has settled"));Object interval=Toolkit.getDefaultToolkit().getDesktopProperty("awt.multiClickInterval");Thread.sleep((interval instanceof Number n?Math.max(250,n.intValue()):500)+250L);FeatureTest.edt(()->{check(opens.get()==1,"double click opens exactly once");check(panel[0].sessions.size()==1&&!panel[0].archived.isSelected(),"double click preserves visible active chat");check(Conversations.load(file).messages().size()==1,"saved original intact");for(String lang:I18n.CODES)for(boolean dark:List.of(false,true)){if(dark)com.formdev.flatlaf.FlatDarkLaf.setup();else com.formdev.flatlaf.FlatLightLaf.setup();SwingUtilities.updateComponentTreeUI(frame[0]);I18n.setLanguage(lang);panel[0].translate();panel[0].archived.doClick();frame[0].validate();check(panel[0].resetFilters.getText().equals(I18n.text("Reseteaza filtrele"))&&panel[0].resetFilters.isVisible(),"localized filter reset in each theme "+lang+dark);if(lang.equals("ro")){var image=new java.awt.image.BufferedImage(frame[0].getWidth(),frame[0].getHeight(),java.awt.image.BufferedImage.TYPE_INT_RGB);Graphics2D g=image.createGraphics();frame[0].getRootPane().printAll(g);g.dispose();javax.imageio.ImageIO.write(image,"png",root.resolve(dark?"filter-dark.png":"filter-light.png").toFile());}panel[0].resetFilters.doClick();}frame[0].dispose();});
  System.out.println("PASS: "+checks+" sidebar filter/double-click checks; synthetic AWT events, no native mouse");System.exit(0);
 }
}
